      "activity_name": "U2 Implementation & Test",
      "activity_description": "Refactor and implement the Redis counter as a s-c-s compatible module, including configuration and integration tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A5",
      "activity_name": "U3 CI Setup & Configuration",
      "activity_description": "Configure GitHub Actions workflow for the s-c-d repository, including build, test, and basic reporting steps.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6",
      "activity_name": "U4 Dependency Resolver Design",
      "activity_description": "Design the mechanism to parse module dependency metadata (e.g., from a manifest) and resolve JARs.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A7",
      "activity_name": "U4 Resolver Implementation & Boot Integration",
      "activity_description": "Implement the dependency resolver and integrate it with the Spring Boot loader's classpath handling for modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "U5 ModuleLauncher Analysis",
      "activity_description": "Analyze the current ModuleLauncher to identify parts to be replaced or enhanced by Spring Boot's application context and properties.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A9",
      "activity_name": "U5 Bootify ModuleLauncher & Test",
      "activity_description": "Refactor ModuleLauncher to extend a Spring Boot application, adding property support and writing tests.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A10",
      "activity_name": "U6 PHD/HDFS Investigation",
      "activity_description": "Spike investigation: analyze PHD dependencies, HDFS module requirements, and prototype a classpath/isolation approach.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "U7 REST Support Design",
      "activity_description": "Design the new REST endpoints for stream commands, including request/response DTOs and controller structure.",
      "most_likely_effort": 8
    },
